#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mode;
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_amount;
uniform float amzp_scl;
uniform float amzp_tilt;
uniform float amzp_bigD;
uniform float amzp_smallD;
uniform float amzp_dSize;
uniform float amzp_speed;
uniform float amzp_stick;
uniform float amzp_meander;
uniform float amzp_trailL;
uniform float amzp_beads;
uniform float amzp_sAmt;
uniform float amzp_sSize;
uniform float amzp_evap;
uniform float amzp_sStrX;
uniform float amzp_sStrY;
uniform float amzp_refr;
uniform float amzp_fog;
uniform float amzp_fogClear;
uniform float amzp_haze;
uniform float amzp_spec;
uniform float amzp_rim;
uniform float amzp_mixAmt;
uniform float amzp_seed;
uniform float amzp_quality;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float h1(float n) { return fract(sin(n * 12.9898 + amzp_seed * 7.137) * 43758.5453); }
    float h2(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    float vn(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f); }
    float PXQ;
    float T;
    float4 slide(float2 p, float lanes, float dens, float k, out float3 nr) {
        float4 res = float4(0.0);
        nr = float3(0.0, 0.0, 1.0);
        if (dens <= 0.0) return res;
        float2 q = p * lanes;
        float pxq = PXQ * lanes;
        float li = floor(q.x);
        float lx = fract(q.x) - 0.5;
        float Y = q.y;
        float hs = h2(float2(li, k));
        float v = mix(0.25, 0.75, hs) * amzp_speed;
        float rate = mix(0.35, 1.1, h2(float2(li, k + 1.0)));
        float tau = T * rate + hs * 10.0;
        float f = fract(tau);
        float slip = smoothstep(0.5, 1.0, f);
        float D = v / rate * (floor(tau) + mix(f, slip, amzp_stick));
        float sp = mix(2.2, 4.5, h2(float2(li, k + 2.0)));
        float u = Y - D;
        float cell = floor(u / sp);
        float loc = u - cell * sp;
        float2 cid = float2(li, cell + k * 131.0);
        if (h2(cid) > dens) return res;
        float hp = sp * (0.5 + (h2(cid + 3.1) - 0.5) * 0.4);
        float dy = loc - hp;
        float ph = li * 7.31 + k * 3.7;
        float r = mix(0.13, 0.24, h2(cid + 5.3)) * amzp_dSize;
        float lim = max(0.5 - r * 1.05, 0.0);
        float xc = (vn(Y * 0.45 + ph) - 0.5) * 0.55 * amzp_meander + (vn(Y * 1.7 + ph * 2.0) - 0.5) * 0.14 * amzp_meander;
        xc = clamp(xc, -lim, lim);
        float dx = lx - xc;
        float ry = dy > 0.0 ? r * 0.92 : r * 1.35;
        float2 qd = float2(dx / r, dy / ry);
        float d = length(qd);
        float aa = pxq / r * 1.5;
        float head = 1.0 - smoothstep(1.0 - aa, 1.0, d);
        if (head > 0.0) {
            float hz = sqrt(max(1.0 - d * d, 0.0));
            res.xy = -float2(qd.x, -qd.y) * r * (0.6 + 1.4 * (1.0 - hz)) / lanes * amzp_refr;
            res.z = head;
            res.w = 1.0;
            nr = float3(qd, hz);
            return res;
        }
        float tl = sp * 0.85 * amzp_trailL;
        if (dy < 0.0 && -dy < tl) {
            float a = -dy / max(tl, 1e-4);
            float tw = r * 0.5 * sqrt(1.0 - a);
            float tr = 1.0 - smoothstep(tw - pxq, tw + pxq, abs(dx));
            res.w = tr * (1.0 - a * 0.6);
            res.xy = float2(-sign(dx) * tr * 0.08 * r / lanes * amzp_refr, 0.0);
            if (amzp_beads > 0.0) {
                float bf = 2.6 / max(r, 0.05);
                float by = floor(Y * bf * 0.35);
                float2 bid = float2(li, by + k * 77.0);
                if (h2(bid + 1.7) < amzp_beads * 0.8) {
                    float byc = (by + 0.5) / (bf * 0.35);
                    float bxc = (vn(byc * 0.45 + ph) - 0.5) * 0.55 * amzp_meander + (vn(byc * 1.7 + ph * 2.0) - 0.5) * 0.14 * amzp_meander;
                    bxc = clamp(bxc, -lim, lim) + (h2(bid + 2.9) - 0.5) * r * 0.5;
                    float br = r * mix(0.18, 0.38, h2(bid + 4.4)) * (1.0 - a * 0.5);
                    float2 bq = float2(lx - bxc, Y - byc) / br;
                    float bd = length(bq);
                    float bm = 1.0 - smoothstep(1.0 - pxq / br * 1.5, 1.0, bd);
                    if (bm > 0.0) {
                        float bz = sqrt(max(1.0 - bd * bd, 0.0));
                        res.xy = -float2(bq.x, -bq.y) * br * (0.6 + 1.4 * (1.0 - bz)) / lanes * amzp_refr;
                        res.z = bm;
                        nr = float3(bq, bz);
                    }
                }
            }
        }
        return res;
    }
    float zz(float x) { float i = floor(x), f = fract(x); f = smoothstep(0.0, 1.0, smoothstep(0.0, 1.0, f) * 0.35 + f * 0.65); return mix(h1(i), h1(i + 1.0), f); }
    float pathX(float Y, float ph) {
        float x = (zz(Y * 0.6 + ph) - 0.5) * 0.75 + (vn(Y * 0.22 + ph * 1.3) - 0.5) * 0.7 + (vn(Y * 2.4 + ph * 2.1) - 0.5) * 0.1;
        return clamp(x * amzp_meander, -0.95, 0.95);
    }
    float swell(float Y, float ph) {
        float b = vn(Y * 1.35 + ph * 3.0);
        return 0.45 + 1.75 * pow(b, 2.5);
    }
    float4 stream(float2 p, float lanes, float dens, float k, out float3 nr) {
        float4 res = float4(0.0);
        nr = float3(0.0, 0.0, 1.0);
        if (dens <= 0.0) return res;
        float2 q = p * lanes;
        float pxq = PXQ * lanes;
        float Y = q.y;
        float best = 0.0;
        for (int j = -1; j <= 1; j++) {
            float li = floor(q.x) + float(j);
            float hs = h2(float2(li, k));
            float v = mix(0.25, 0.75, hs) * amzp_speed;
            float rate = mix(0.35, 1.1, h2(float2(li, k + 1.0)));
            float tau = T * rate + hs * 10.0;
            float f = fract(tau);
            float slip = smoothstep(0.5, 1.0, f);
            float D = v / rate * (floor(tau) + mix(f, slip, amzp_stick));
            float sp = mix(5.0, 9.0, h2(float2(li, k + 2.0)));
            float u = Y - D;
            float cell = floor(u / sp);
            float loc = u - cell * sp;
            float2 cid = float2(li, cell + k * 131.0);
            if (h2(cid) > dens) continue;
            float hp = sp * (0.86 + (h2(cid + 3.1) - 0.5) * 0.1);
            float dy = loc - hp;
            float ph = li * 7.31 + k * 3.7;
            float r = mix(0.075, 0.13, h2(cid + 5.3)) * amzp_dSize;
            float x0 = q.x - (li + 0.5);
            float4 cur = float4(0.0);
            float3 cn = float3(0.0, 0.0, 1.0);
            float m = 0.0;
            float dxh = x0 - pathX(Y - dy, ph);
            float ry = dy > 0.0 ? r * 1.0 : r * 1.25;
            float2 qd = float2(dxh / r, dy / ry);
            float d = length(qd);
            float hm = 1.0 - smoothstep(1.0 - pxq / r * 1.5, 1.0, d);
            if (hm > 0.0) {
                float hz = sqrt(max(1.0 - d * d, 0.0));
                cur = float4(-float2(qd.x, -qd.y) * r * (0.6 + 1.6 * (1.0 - hz)) / lanes * amzp_refr, hm, 1.0);
                cn = float3(qd, hz);
                m = hm;
            }
            float tl = min(sp * 0.86 * amzp_trailL, hp);
            if (m < 0.999 && dy < 0.0 && -dy < tl) {
                float a = -dy / max(tl, 1e-4);
                float taper = 0.25 + 0.75 * pow(1.0 - a, 0.45);
                float join = exp(dy / (r * 2.2));
                float w0 = r * 0.42 * swell(Y, ph) * taper;
                float tw = mix(w0, r * 0.8, join);
                float dx = x0 - pathX(Y, ph);
                float tr = 1.0 - smoothstep(tw - pxq, tw + pxq, abs(dx));
                if (tr > m) {
                    float cx = clamp(dx / max(tw, 1e-4), -1.0, 1.0);
                    float cz = sqrt(max(1.0 - cx * cx, 0.0));
                    float zz2 = tr * (1.0 - a * 0.25);
                    cur = float4(-float2(cx, 0.0) * (r * 0.15) * (0.6 + 0.7 * (1.0 - cz)) / lanes * amzp_refr, zz2, 1.0);
                    cn = float3(cx, 0.0, cz);
                    m = tr;
                }
                if (amzp_beads > 0.0) {
                    float bf = 1.6 / max(r, 0.05);
                    float by = floor(Y * bf * 0.3);
                    float2 bid = float2(li, by + k * 77.0);
                    if (h2(bid + 1.7) < amzp_beads * 0.55) {
                        float byc = (by + 0.5) / (bf * 0.3);
                        float side = h2(bid + 2.9) < 0.5 ? -1.0 : 1.0;
                        float br = r * mix(0.22, 0.45, h2(bid + 4.4));
                        float bxc = pathX(byc, ph) + side * (r * 0.42 * swell(byc, ph) + br * mix(0.6, 2.2, h2(bid + 6.1)));
                        float2 bq = float2(x0 - bxc, Y - byc) / br;
                        float bd = length(bq);
                        float bm = 1.0 - smoothstep(1.0 - pxq / br * 1.5, 1.0, bd);
                        if (bm > m) {
                            float bz = sqrt(max(1.0 - bd * bd, 0.0));
                            cur = float4(-float2(bq.x, -bq.y) * br * (0.6 + 1.4 * (1.0 - bz)) / lanes * amzp_refr, bm, max(cur.w, 0.0));
                            cn = float3(bq, bz);
                            m = bm;
                        }
                    }
                }
            }
            if (m > best) { best = m; res = cur; nr = cn; }
        }
        return res;
    }
    float3 beadsAt(float2 p, float cells, float k, float rmin, float rmax, out float3 nr) {
        nr = float3(0.0, 0.0, 1.0);
        float2 sx = float2(clamp(amzp_sStrX, 0.2, 4.0), clamp(amzp_sStrY, 0.2, 4.0));
        float2 q = p * cells / sx;
        float2 id = floor(q);
        float2 f = fract(q) - 0.5;
        float2 c = (float2(h2(id + k), h2(id + k + 9.1)) - 0.5) * 0.6;
        float life = fract(T * 0.04 * amzp_evap + h2(id + k + 3.3));
        float g = smoothstep(0.0, 0.2, life) * (1.0 - smoothstep(0.75, 1.0, life));
        if (amzp_evap <= 0.0) g = 1.0;
        float r = mix(rmin, rmax, h2(id + k + 5.7)) * amzp_sSize * g;
        if (h2(id + k + 7.7) > amzp_sAmt || r <= 0.0) return float3(0.0);
        float2 dq = (f - c) / r;
        float d = length(dq);
        float aa = PXQ * cells / (r * max(sx.x, sx.y)) * 1.5;
        float m = 1.0 - smoothstep(1.0 - aa, 1.0, d);
        if (m <= 0.0) return float3(0.0);
        float z = sqrt(max(1.0 - d * d, 0.0));
        nr = float3(dq.x, -dq.y, z);
        return float3(-float2(dq.x, -dq.y) * r * sx * (0.5 + 1.2 * (1.0 - z)) / cells * amzp_refr, m);
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 src = amzTexture(0, l2s(uv));
        T = (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress;
        float S = max(amzp_scl, 0.1);
        float a = radians(amzp_tilt);
        float2 p = (uv - 0.5) * W / W.y;
        p.y = -p.y;
        float cs = cos(a), sn = sin(a);
        p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y) / S;
        PXQ = 1.0 / (W.y * S);
        float am = clamp(amzp_amount, 0.0, 1.0);
        float3 nA, nB, n1, n2;
        float4 A, B;
        if (int(amzp_mode) == 1) {
            A = stream(p, 5.0, amzp_bigD * am, 1.0, nA);
            B = stream(p + float2(0.37, 0.0), 9.0, amzp_smallD * am, 2.0, nB);
        } else {
            A = slide(p, 4.5, amzp_bigD * am, 1.0, nA);
            B = slide(p + float2(0.37, 0.0), 9.0, amzp_smallD * am, 2.0, nB);
        }
        float3 s1 = beadsAt(p, 26.0, 11.0, 0.12, 0.32, n1);
        float3 s2 = beadsAt(p + 0.13, 60.0, 23.0, 0.10, 0.28, n2);
        float trail = max(A.w, B.w);
        float wipe = 1.0 - clamp(trail * 1.5, 0.0, 1.0);
        s1.z *= wipe * am; s2.z *= wipe * am;
        float2 off = float2(0.0);
        float water = 0.0;
        float3 nn = float3(0.0, 0.0, 1.0);
        if (s2.z > water) { off = s2.xy; water = s2.z; nn = n2; }
        if (s1.z > water) { off = s1.xy; water = s1.z; nn = n1; }
        if (B.z > 0.0) { off = mix(off, B.xy, B.z); water = max(water, B.z); nn = nB; }
        if (A.z > 0.0) { off = mix(off, A.xy, A.z); water = max(water, A.z); nn = nA; }
        if (water <= 0.0 && trail > 0.0) off = A.w > B.w ? A.xy : B.xy;
        float2 o2 = off * S;
        o2 = float2(cs * o2.x - sn * o2.y, sn * o2.x + cs * o2.y);
        o2.y = -o2.y;
        float2 ouv = o2 * W.y / W;
        float2 suv = clamp(uv + ouv, 0.0, 1.0);
        float4 sharp = amzTexture(0, l2s(suv));
        float clearAmt = clamp(max(water, trail * 0.85) * amzp_fogClear, 0.0, 1.0);
        float4 col = sharp;
        if (amzp_fog > 0.0 && clearAmt < 1.0) {
            float nq = amzp_quality < 1.5 ? 4.0 : (amzp_quality < 2.5 ? 8.0 : (amzp_quality < 3.5 ? 12.0 : (amzp_quality < 4.5 ? 16.0 : 24.0)));
            float4 acc = sharp;
            for (int i = 0; i < 24; i++) {
                float fi = float(i);
                if (fi >= nq) break;
                float rr = sqrt((fi + 0.5) / nq) * amzp_fog;
                float ang = fi * 2.399963;
                acc += amzTexture(0, l2s(clamp(suv + float2(cos(ang), sin(ang)) * rr / W, 0.0, 1.0)));
            }
            float4 fogged = acc / (nq + 1.0);
            fogged.rgb = mix(fogged.rgb, float3(fogged.a), amzp_haze);
            col = mix(fogged, sharp, clearAmt);
        } else if (amzp_haze > 0.0) {
            col.rgb = mix(col.rgb, float3(col.a), amzp_haze * (1.0 - clearAmt));
        }
        if (water > 0.0) {
            float edge = length(nn.xy);
            col.rgb *= 1.0 - amzp_rim * smoothstep(0.6, 1.0, edge) * water;
            float3 N = normalize(float3(nn.xy, max(nn.z, 0.05)));
            float g = max(dot(N, normalize(float3(-0.45, -0.6, 0.66))), 0.0);
            float glint = pow(g, 40.0) + 0.25 * pow(max(dot(N, normalize(float3(0.3, 0.7, 0.65))), 0.0), 18.0);
            col.rgb += float3(glint * amzp_spec) * col.a * water;
        }
        col.rgb = clamp(col.rgb, 0.0, max(col.a, 0.0));
        float4 res = float4(col.rgb / max(col.a, 1e-4), 1.0) * src.a;
        amzOutput = mix(src, res, clamp(amzp_mixAmt, 0.0, 1.0));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
